import type { CodeBlockProps } from "./code-block.types";
import type { editor } from "monaco-editor";

import { forwardRef, useState } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useUniqueId } from "@system";
import { Editor } from "@monaco-editor/react";
import { Resizable, type ResizableProps } from "re-resizable";

import { CodeBlockClasses, StyledCodeBlock } from "./code-block.styles";
import { useCodeBlockState } from "./hooks/use-code-block-state";
import { resolveTypographyForMonaco } from "./utils/resolve-typography";

const CodeBlock = forwardRef<editor.IStandaloneCodeEditor, CodeBlockProps>(
  (
    {
      className,
      size = "default",
      variant = "default",
      options,
      theme: monacoTheme = "light",
      defaultLanguage = "javascript",
      defaultWidth = "100%",
      defaultHeight = "100%",
      onMount,
      onResizeStart,
      onResize,
      onResizeStop,
      style,
      resize = "both",
      name,
      "aria-label": ariaLabel,
      id,
      disabled = false,
      readOnly = false,
      onChange,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const generatedId = useUniqueId("code-block");
    const codeBlockId = id || generatedId;
    const { height, width, handleEditorDidMount } = useCodeBlockState({
      defaultHeight,
      defaultWidth,
      ref,
      onMount,
      id: codeBlockId,
    });
    const typographyConfig = size === "sm" ? theme.typography.code.sm : theme.typography.code.md;
    const typography = resolveTypographyForMonaco(typographyConfig, theme);
    const resizable = resize !== "none";

    // Store latest value for submission. For uncontrolled usage we capture initial defaultValue from props.
    const initialDefaultValue = (props as { defaultValue?: string }).defaultValue;
    const [uncontrolledValue, setUncontrolledValue] = useState(initialDefaultValue);
    const latestValue = props.value ?? uncontrolledValue;

    const { required } = props;
    const effectiveReadOnly = readOnly || disabled;

    const editorElement = (
      <StyledCodeBlock
        aria-disabled={disabled ? true : undefined}
        className={clsx(CodeBlockClasses.root, className)}
        currentTheme={theme}
        data-name={name}
        style={{
          width: resizable ? "100%" : width,
          height: resizable ? "100%" : height,
          ...style,
        }}
        variant={variant}
      >
        <input name={name} type="hidden" value={latestValue} />
        <Editor
          defaultLanguage={defaultLanguage}
          height="100%"
          options={{
            ...typography,
            automaticLayout: true,
            readOnly: effectiveReadOnly,
            ariaLabel: ariaLabel,
            ariaRequired: required,
            ...options,
          }}
          theme={monacoTheme}
          width="100%"
          onChange={(val) => {
            if (typeof props.value === "undefined") {
              setUncontrolledValue(val);
            }
            onChange?.(val);
          }}
          onMount={handleEditorDidMount}
          {...props}
        />
      </StyledCodeBlock>
    );

    let resizableProps: ResizableProps = {
      onResizeStart,
      onResizeStop,
      onResize,
    };
    if (resize === "horizontal") {
      resizableProps = {
        ...resizableProps,
        minHeight: defaultHeight,
        maxHeight: defaultHeight,
        handleStyles: {
          bottom: { display: "none" },
          top: { display: "none" },
          topRight: { display: "none" },
          bottomRight: { display: "none" },
          bottomLeft: { display: "none" },
          topLeft: { display: "none" },
        },
      };
    } else if (resize === "vertical") {
      resizableProps = {
        ...resizableProps,
        minWidth: defaultWidth,
        maxWidth: defaultWidth,
        handleStyles: {
          left: { display: "none" },
          right: { display: "none" },
          topRight: { display: "none" },
          bottomRight: { display: "none" },
          bottomLeft: { display: "none" },
          topLeft: { display: "none" },
        },
      };
    }

    if (resizable) {
      return (
        <Resizable
          defaultSize={{
            width: width,
            height: height,
          }}
          {...resizableProps}
        >
          {editorElement}
        </Resizable>
      );
    } else {
      return editorElement;
    }
  },
);

CodeBlock.displayName = "CodeBlock";

export default CodeBlock;
